import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Обновление сервера и клиентов","description":"","frontmatter":{"pageId":"admins/updating","contentRevision":1},"headers":[],"relativePath":"ru/admins/updating.md","filePath":"ru/admins/updating.md"}'),r={name:"ru/admins/updating.md"};function o(n,a,s,d,p,u){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="обновление-сервера-и-клиентов" tabindex="-1">Обновление сервера и клиентов <a class="header-anchor" href="#обновление-сервера-и-клиентов" aria-label="Permalink to &quot;Обновление сервера и клиентов&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol><li>Прочитай изменения релиза и сверяй сервер/мод/набор модов.</li><li>Объяви обслуживание, заверши сессии штатно и сделай согласованную резервную копию. Запиши используемую версию и настройки.</li><li>Проверь обновление на отдельной копии данных. Миграции EF применяются при старте; сохраняй старый snapshot до проверки.</li><li>Замени сервер, затем обнови клиентский мод с закрытой игрой. Пересобери/перепубликуй разрешённый набор при изменении требований.</li><li>Проверь вход, загрузку/отправку сейва, почту и модпак. Открой доступ после успешной проверки.</li></ol><p>При неудаче останови новый сервер. Возвращай совместимый комплект старого сервера и проверенной копии данных; простая замена бинарника после миграции не гарантирует совместимость.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Версия протокола меняется только при несовместимом контракте, но одинаковый протокол не отменяет требований к модам. Не обновляй общий каталог игры чужого сеанса. Публикация пакета требует отдельного решения оператора.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./backup-recovery">Резервные копии и восстановление</a></li><li><a href="./../compatibility">Версии и совместимость</a></li><li><a href="./modpacks">Управление набором модов</a></li></ul>',9)])])}const m=e(r,[["render",o]]);export{h as __pageData,m as default};
